begin;
select plan(29);
insert into auth.users(id,is_anonymous) values('f1000000-0000-4000-8000-000000000001',true),('f1000000-0000-4000-8000-000000000002',true),('f1000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"is_anonymous":true}',true);
select is(public.create_code_band('New band','Leader','기타','1234','112233')->>'ok','true','create without administrator PIN');
select set_config('test.new.band',public.current_band_identity()->>'band_id',true);
select public.set_member_skill_enabled(true);
select set_config('test.new.code',public.band_login_settings()->>'code',true);
select set_config('test.new.me',public.current_band_identity()->'member'->>'id',true);
select is((select skill from public.band_members where id=current_setting('test.new.me')::uuid),null::smallint,'new leader skill unassigned');
select is(public.band_home_context()->>'unset_skills','1','home counts unset skills');
select set_config('test.new.first',public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+1,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false)::text,true);
select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false);
select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+3,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false);
select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+4,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false);
select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+5,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false);
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+6,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false)$$,'P0001','PLAN_LIMIT_REACHED','five upcoming plans enforced');
reset role;
update public.confirmed_plans set rehearsal_date=(now() at time zone 'Asia/Seoul')::date-1 where id=current_setting('test.new.first')::uuid;
select is((select count(*)::int from private.band_login_credentials where admin_pin_hash is not null),0,'retired administrator PIN hashes cleared');
select is((select skill from public.band_members where user_id='c1000000-0000-4000-8000-000000000001'),3::smallint,'preexisting explicit skill preserved');
set local role authenticated;
select lives_ok($$select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+6,'{}',(public.band_planning_context()->>'version')::bigint,null,null,false)$$,'past plan frees capacity without deletion');
select is((select count(*)::int from public.confirmed_plans where band_id=current_setting('test.new.band')::uuid),6,'past and upcoming plans all retained');
select is((select count(*)::int from public.confirmed_plan_members where plan_id=current_setting('test.new.first')::uuid),1,'archived participant snapshot preserved');
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+7,'{}',(public.band_planning_context()->>'version')::bigint,current_setting('test.new.first')::uuid,1,false)$$,'P0001','PLAN_LIMIT_REACHED','cannot bypass upcoming cap by restoring past plan');
select set_config('test.new.song',public.add_song(current_setting('test.new.band')::uuid,'Song','Artist')::text,true);
select public.update_song_difficulty(current_setting('test.new.song')::bigint,'기타',2::smallint,0);
select public.vote_band_song(current_setting('test.new.song')::bigint,'yes',null);
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+1,array[current_setting('test.new.song')::bigint],(public.band_planning_context()->>'version')::bigint,current_setting('test.new.first')::uuid,1,false)$$,'P0001','PLAN_LIMIT_REACHED','archive-cap check remains serialized');
select set_config('test.new.edit',(select id::text from public.confirmed_plans where band_id=current_setting('test.new.band')::uuid and rehearsal_date=(now() at time zone 'Asia/Seoul')::date+2),true);
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,array[current_setting('test.new.song')::bigint],(public.band_planning_context()->>'version')::bigint,current_setting('test.new.edit')::uuid,1,false)$$,'P0001','SONG_NOT_ELIGIBLE','unset skill prevents selecting a newly recommended song');
select lives_ok($$select public.update_member_skill(current_setting('test.new.me')::uuid,3::smallint)$$,'leader explicitly sets skill');
select lives_ok($$select public.save_rehearsal_plan(current_setting('test.new.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,array[current_setting('test.new.song')::bigint],(public.band_planning_context()->>'version')::bigint,current_setting('test.new.edit')::uuid,1,false)$$,'song becomes selectable after skill set');

select lives_ok($$select public.update_member_skill(current_setting('test.new.me')::uuid,null)$$,'leader can clear skill to unassigned');
select is(public.band_home_context()->>'pending_votes','0','home excludes own submitted votes');
select public.add_song(current_setting('test.new.band')::uuid,'Pending song','Artist');
select is(public.band_home_context()->>'pending_votes','1','home counts only unanswered songs');
select public.save_band_unavailability(jsonb_build_array(jsonb_build_object('date',((now() at time zone 'Asia/Seoul')::date+20)::text)));
select is(jsonb_array_length(public.band_home_context()->'upcoming_unavailable'),1,'home includes own upcoming unavailable dates');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000002',true);
select public.begin_band_access(current_setting('test.new.code'),'1234');
select public.register_band_profile('Member','베이스','246810');
select set_config('test.new.target',public.current_band_identity()->'member'->>'id',true);
select is(public.band_home_context()->>'pending_votes','2','new member home has independent pending votes');
select is(jsonb_array_length(public.band_home_context()->'upcoming_unavailable'),0,'home never includes another member dates');
select is(public.band_home_context()->>'unset_skills','2','new member starts unassigned too');
select throws_ok($$select public.transfer_leadership(current_setting('test.new.band')::uuid,current_setting('test.new.me')::uuid)$$,'P0001','FORBIDDEN','member cannot transfer leadership');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.transfer_leadership(current_setting('test.new.band')::uuid,current_setting('test.new.target')::uuid)$$,'leader handoff needs no administrator PIN');
select throws_ok($$select public.update_member_skill(current_setting('test.new.me')::uuid,3::smallint)$$,'P0001','FORBIDDEN','old leader immediately loses authority');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.update_member_skill(current_setting('test.new.target')::uuid,4::smallint)$$,'new leader manages immediately');
select is(public.configure_band_login('new1234')->>'ok','true','password rotation without administrator PIN');
select is(public.current_band_identity()->>'id','f1000000-0000-4000-8000-000000000002','rotation preserves current leader session');
select set_config('request.jwt.claim.sub','f1000000-0000-4000-8000-000000000003',true);
select is(public.band_home_context(),null::jsonb,'unmapped guest home is inaccessible');
select ok(not has_function_privilege('anon','public.band_home_context()','execute'),'home summary denies anonymous role');
select * from finish();rollback;
